gs={'A^q exp(-A)':lambda A,q: A**q*np.exp(-A),'A^q':lambda A,q: A**q,'A/(1+qA)':lambda A,q: A/(1+q*A),'exp(-qA)':lambda A,q: np.exp(-q*A),'A exp(-qA)':lambda A,q: A*np.exp(-q*A),'log(1+qA)':lambda A,q: np.log(1+q*A),'log(1+A)^2':lambda A,q: np.log(1+A)**2,'A^2/(1+A)':lambda A,q:A**2/(1+A),'A exp(-A^2 q)':lambda A,q:A*np.exp(-q*A**2),'1/(1+qA)':lambda A,q:1/(1+q*A),'A/(1+A)^q':lambda A,q:A/(1+A)**q}
